$ProjectDir = "C:\ollama\cvn_node"; $BackupDir = "C:\ollama\cvn_node\backups"; if (!(Test-Path -Path $BackupDir)) { New-Item -ItemType Directory -Path $BackupDir | Out-Null }; Write-Host "--- INITIALIZING IMMUTABLE BACKGROUND LEDGER BACKUP LOOP ---" -ForegroundColor Cyan; while ($true) { if (Test-Path -Path "$ProjectDir\ledger_vault.json") { $Timestamp = Get-Date -Format "yyyyMMdd_HHmmss"; Copy-Item -Path "$ProjectDir\ledger_vault.json" -Destination "$BackupDir\ledger_vault_backup_$Timestamp.json" -Force; Write-Host "SUCCESS: Fork-proof timestamped backup written cleanly to separate backups directory!" -ForegroundColor Green } else { Write-Host "WARNING: Live ledger_vault.json file not found in main directory path." -ForegroundColor Yellow }; Start-Sleep -Seconds 86400 }